(function() {
  var isRNWebView = !!window.ReactNativeWebView;
  var originalPostMessage = window.postMessage;

  // RN WebView 环境下劫持 postMessage：
  // - setImmediate 消息走原生通道（RN 内部调度依赖）
  // - 其他消息统一走 ReactNativeWebView.postMessage
  window.postMessage = function(data, targetOrigin, transfer) {
    if (isRNWebView && typeof data === 'string' && data.match(/^setImmediate[\$#]/)) {
      originalPostMessage.call(this, data, targetOrigin, transfer);
    } else if (isRNWebView) {
      window.ReactNativeWebView.postMessage(typeof data === 'string' ? data : JSON.stringify(data));
    } else {
      originalPostMessage.call(this, data, targetOrigin, transfer);
    }
  };

  // setImmediate polyfill：优先 queueMicrotask > Promise > setTimeout
  try {
    window.setImmediate = function(callback) {
      if (typeof queueMicrotask === 'function') {
        queueMicrotask(callback);
      } else if (typeof Promise === 'function') {
        Promise.resolve().then(callback);
      } else {
        setTimeout(callback, 0);
      }
    };
  } catch(e) {}

  true;
})();


